    ["7496082"] = "Zygor 天赋标记：",
    ["1b9f260"] = "请重新打开天赋窗口。",
    ["7c4161e"] = "切换目标时不会中断自动射击。",
    ["3ddfa3b"] = "宠物攻击你用 Hunter's Mark 标记的目标。",
    ["d00e00c"] = "一个按键使用近战技能，用于被攻击时。",
    ["458bcf6"] = "在闪避或招架之后，用一个按键轮流使用 Mongoose Bite 和 Counterattack。",
    ["7e3322d"] = "施放技能并开始自动攻击，甚至在进入战斗之前。可以用别的技能代替 Heroic Strike。需要足够的怒气。",
    ["4215a24"] = "对光标下的敌人施放 Sunder Armor，无需选中它。",
    ["fade647"] = "对光标下的盟友施放 Blessing of Protection（没有则对你的目标）。",
    ["0ea3265"] = "对光标下的盟友施放 Blessing of Freedom。",
    ["474ed6a"] = "对光标下的盟友施放 Cleanse。",
    ["dd398c9"] = "在光标处召唤 Advanced Target Dummy 并对它施放 Blessing of Protection：在没有公共冷却时按两次。",
    ["ad171ca"] = "对自己施放 Divine Shield；再按一次立刻取消。在没有公共冷却时按两次。",
    ["8b1f0a2"] = "开始自动攻击并施放 Holy Strike。不要放在 Holy Shield 上。",
    ["39da0a5"] = "对光标目标施放 Power Word: Shield，否则对自己。",
    ["885b4fd"] = "对光标目标施放 Greater Heal，否则对当前目标，否则对自己。",
    ["f6044e4"] = "停止当前施法并重新施放 Greater Heal：当另一名治疗已经治疗了该目标时使用。",
    ["73afb8f"] = "Inner Focus，紧接着 Prayer of Healing：用于紧急情况。",
    ["91996ef"] = "智能 Dispel Magic：驱散盟友身上的有害魔法和敌人身上的有益魔法。",
    ["b32d1df"] = "对光标目标施放 Prayer of Mending，否则对当前目标，否则对自己。",
    ["4e5454e"] = "停止施法，对正在逃跑的濒死怪物或图腾使用 Shadow Word: Death。",
    ["4b2ea52"] = "给主手武器涂抹 Deadly Poison；图标显示持续时间。",
    ["73d1f2d"] = "给副手武器涂抹 Instant Poison；图标显示持续时间。",
    ["672d6cc"] = "以 Pick Pocket 开场，然后 Garrote（可以换成 Cheap Shot 或 Ambush）。",
    ["c2da64b"] = "用一个按键让宠物和角色一起攻击：这样升级时你不会站着不动。",
    ["8833bc9"] = "与 BB Attacco 相同，但还会施放 Stormstrike（代替前一个宏）。",
    ["79e760c"] = "在光标所在位置施放 Totemic Projection。",
    ["93ec012"] = "Nature's Swiftness，紧接着对光标目标施放 Healing Wave：瞬发的紧急治疗。如果不想用光标治疗，请删掉 [@mouseover]。",
    ["ddfe74e"] = "对焦点目标施放 Polymorph；如果没有焦点或不是敌人，则对当前目标。",
    ["425c144"] = "用一个按键使用两个饰品（栏位13和14）。",
    ["23fc3c4"] = "Combustion 与两个饰品一起使用。",
    ["6d5d784"] = "让宠物攻击，然后设为被动，如指南所述。",
    ["3b9d855"] = "Amplify Curse 和 Bane of Agony 一起使用：用于开场或 Amplify Curse 就绪时。",
    ["67eb4db"] = "可以连续多次按下而不会打断自己的 Drain Life。",
    ["c24583f"] = "对光标下的目标施放 Corruption：用来给多个敌人上 DOT。把 Corruption 换成别的 DOT 即可。",
    ["de046d0"] = "Fel Domination，紧接着 Imp：用于宠物死亡后重新召唤，或用于收割流派。",
    ["0da2d35"] = "Fel Domination，紧接着 Succubus：用于宠物死亡后重新召唤。",
    ["701f8c9"] = "对光标下的目标施放 Bane of Havoc。",
    ["6177927"] = "对焦点（Bane of Havoc 的目标）施放 Immolate。",
    ["687eb32"] = "对焦点施放 Corruption。",
    ["dfc9982"] = "对焦点施放 Bane of Doom。",
    ["f14c9c9"] = "对焦点施放 Bane of Agony。",
    ["37f2591"] = "在施法期间按键也不会自己打断的 Hurricane。",
    ["e041704"] = "对光标目标施放 Moonfire：用来给多个敌人上 DOT（另一个换成 Insect Swarm）。",
    ["11b387e"] = "Feral Charge（猎豹），然后 Prowl（如果你还没潜行）。",
    ["9bca5ec"] = "变换形态以摆脱定身和减速：从熊到猎豹，从猎豹到猎豹。",
    ["38e0846"] = "一个按键：水中用 Aquatic Form，室外用 Travel Form，否则 Cat Form。",
    ["53406a7"] = "只进入一次 Dire Bear Form，再按也不会退出。",
    ["b18da61"] = "对焦点施放 Growl，然后对光标目标，然后对当前目标。",
    ["beb6029"] = "Nature's Swiftness，紧接着 Healing Touch：瞬发的紧急治疗（退出形态并停止施法）。",
    ["8c5c182"] = "战斗中无法创建宏：请稍后再试。",
    ["e3c93a8"] = "宏：创建 %d 个，更新 %d 个%s。用 /macro 打开并拖到动作条上。",
    ["99effc3"] = "%d 个未创建（你已有18个角色宏）",
    ["530c645"] = "这个专精没有宏。",
    ["1e74c8f"] = "BuildBeast 将为你的角色创建 %s 个宏：\n%s\n\n如果已存在则更新。然后你把它们拖到动作条上。",
    ["d8354a3"] = "创建",
    ["160009a"] = "取消",
    ["054716f"] = "战士",
    ["3e76e85"] = "圣骑士",
    ["69c8129"] = "猎人",
    ["dd6c053"] = "潜行者",
    ["3a3f441"] = "牧师",
    ["fabeb14"] = "萨满祭司",
    ["a5a0a92"] = "法师",
    ["8b0635d"] = "术士",
    ["3d8e8ed"] = "德鲁伊",
    ["ce774d9"] = "是",
    ["c2f3f48"] = "否",
    ["672c529"] = "相近",
    ["656ff24"] = "Bear Form, Growl, Maul（职业任务）, Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash；Cure Poison 的任务",
    ["2290f2a"] = "Swipe；Aquatic Form 的任务",
    ["227f378"] = "Faerie Fire（现在在变形状态下也能用）, Hibernate",
    ["469f184"] = "Cat Form（任务）, Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "给自己上 Mark of the Wild。用 Wrath 开场并持续施放。法力不足时用武器收掉怪物，这样法力会回来。战斗之间用 Healing Touch 治疗。",
    ["3d495a9"] = "让 Mark of the Wild 和 Thorns 一直在身上，战斗前先上 Rejuvenation。用 Wrath 开场，加上 Moonfire，然后继续 Wrath。在怪物密集的地方用瞬发的 Moonfire 开场。",
    ["bb21cc8"] = "职业任务会给你 Bear Form、Growl 和 Maul。Nature's Grasp 会缠住下一个打到你的怪物；Demoralizing Roar 用于熊形态。",
    ["a9ba21f"] = "Enrage 立刻给你怒气，10秒后再给一些，但会降低你的护甲。",
    ["9c7f3ca"] = "Feral 是猫和熊的专精，也是升级最顺畅的：Prowl 和 Dash 把你从一个目标带到下一个，几乎不会因为法力而停下。在 Bear Form 中：给自己上 Mark of the Wild 和 Thorns，用打击获得的怒气支付 Maul，它会给下一次打击增加伤害。面对多个怪物用 Demoralizing Roar 削弱它们。",
    ["ce230c2"] = "在 Bear Form 中：拉怪前用 Enrage（护甲损失影响较小），Faerie Fire 降低怪物护甲，Swipe 是填充技能，Maul 消耗多余的怒气。有多个怪物时先 Demoralizing Roar，再 Swipe。",
    ["78a0920"] = "Cat Form：先上 Mark of the Wild 和 Thorns。从 Prowl 用 Shred 开场（Prowl 带你绕到怪物背后），然后 Faerie Fire，再用 Claw 积累连击点，或在背后时用 Shred。有四个或更多连击点时，如果怪物活得够久就用 Rip。面对多个怪物 Bear Form 仍然更好：猫形态没有能同时打多个目标的技能。",
    ["540175c"] = "Rake：从 Prowl 用 Shred 开场，Faerie Fire，然后 Rake，并让它的流血始终保持在活得够久的怪物身上；然后从背后用 Claw 或 Shred。有4个或更多点时：怪物还活着就用 Rip，用 Ferocious Bite 收尾。",
    ["87e3251"] = "Lacerate（熊）：可叠加最多5层的流血；面对单个怪物它是你的填充技能，Maul 消耗多余的怒气。有多个怪物时用 Demoralizing Roar 然后 Swipe。Blood Frenzy：熊形态下每次暴击给5点怒气，猫形态下用连击点技能暴击会多给一个点。",
    ["25dc320"] = "Predatory Discipline：Ferocious Bite 仍会从多余的能量中获得伤害，但不会消耗它。",
    ["042c952"] = "Ravage：从 Prowl 用 Ravage 开场（必须在怪物背后），然后 Faerie Fire，保持流血的 Rake，然后从背后用 Claw 或 Shred；有4个或更多点时用 Rip 或 Ferocious Bite 收尾。如果以满能量开场，Poised 会让你的第一击少消耗10点能量。",
    ["4560b4d"] = "Dire Bear Form：拉怪前用 Enrage，Faerie Fire，每次冷却好就用 Primal Bite（强力撕咬，冷却6秒，威胁很高），面对单个怪物在中间用 Lacerate，用 Maul 消耗剩余怒气；有多个怪物时用 Demoralizing Roar 和 Swipe 代替 Lacerate。",
    ["ff10d54"] = "猫：能量低于50时用 Shifting Power（把法力变成40点能量，冷却8秒）。",
    ["0d8ecd7"] = "Feral 最看重武器的每秒伤害，因为你的形态基于它，而武器速度不重要。然后是命中（Hit）、暴击、敏捷和力量。",
    ["4a841e3"] = "Guardian 就是熊：使用与 Feral 相同的天赋计划。Bear Form，给自己上 Mark of the Wild 和 Thorns；打击得到的怒气支付 Maul。面对多个怪物用 Demoralizing Roar。",
    ["7b551a8"] = "拉怪前 Enrage，对怪物用 Faerie Fire，Swipe 作填充，Maul 消耗多余的怒气。有多个怪物时 Demoralizing Roar 然后 Swipe。",
    ["af4c8fb"] = "Lacerate 是你面对单个怪物的填充技能（最多叠加5层）；Maul 消耗多余的怒气。有多个怪物时用 Demoralizing Roar 和 Swipe。",
    ["5213241"] = "Dire Bear Form：拉怪前 Enrage，Faerie Fire，每次冷却好就用 Primal Bite（6秒，威胁很高），面对单个怪物在中间用 Lacerate，Maul 消耗其余怒气；有多个怪物时用 Demoralizing Roar 和 Swipe 代替 Lacerate。",
    ["fc61247"] = "熊想要武器的每秒伤害（速度不重要），然后是命中（Hit）、暴击、敏捷和力量。熊形态下力量和法术强度也可以，如果你坦怪，耐力更重要。",
    ["25acd2a"] = "Balance 和 Restoration 开局相同：Improved Wrath（施法时间减半秒、法力消耗减半）和 Nature's Focus。Balance 起步慢，但当 Insect Swarm 在每个怪物身上和 Moonfire 叠加时会变快。",
    ["9c1fb9f"] = "给自己上 Mark of the Wild 和 Thorns，战斗前上 Rejuvenation。用 Wrath 开场，区域怪物密集时用 Moonfire。给怪物上 Moonfire 和 Insect Swarm（一个还会降低其命中率的 DOT），然后 Wrath。需要治疗时用 Regrowth，在第二个怪物到来前用 Nature's Grasp。",
    ["7f51b3b"] = "给你战斗的每个怪物上 Moonfire 和 Insect Swarm，然后 Wrath。有三个或更多怪物时用 Hurricane。",
    ["c845919"] = "有三个或更多怪物时，Barkskin 然后 Hurricane。",
    ["d66aa4c"] = "Eclipse：每个 Wrath 会让你接下来的两个 Starfire 各减少半秒，所以 Starfire 终于进入输出循环：一个 Wrath 后接两个 Starfire。",
    ["7e94c11"] = "Moonkin Form：护甲很高，为队伍提供3%暴击，Omen of Clarity 触发率翻倍；处于该形态时不能施放治疗，所以退出形态用 Regrowth 再进入。输出循环：Moonfire 和 Insect Swarm，然后一个 Wrath 和两个 Starfire。",
    ["ef6797a"] = "对 Balance 和 Restoration，法术强度排第一，然后是智力、暴击和精神；Restoration 在60级加上治疗强度。施法者法杖可以来自阵营任务。",
    ["a91a8ac"] = "Restoration 升级最慢，因为治疗不能杀怪：你可以用 Balance 或 Feral 升级，仍然可以治疗副本。",
    ["7a2110b"] = "给自己上 Mark of the Wild 和 Thorns，战斗前上 Rejuvenation。在怪物密集的区域用 Wrath 或 Moonfire 开场，然后给怪物上 Moonfire 和 Insect Swarm，再 Wrath。需要治疗时用 Regrowth，在第二个怪物到来前用 Nature's Grasp。",
    ["937f66e"] = "Swiftmend：瞬间治疗带有你的 Rejuvenation 或 Regrowth 的目标。受到伤害时，对你的 Rejuvenation 用 Swiftmend，需要更多时再用 Regrowth。有三个或更多怪物时用 Hurricane。",
    ["2061d06"] = "Nature's Swiftness：你的下一个自然法术是瞬发。把它放在输出循环之外，留给需要立刻大量治疗的时刻。",
    ["1164b95"] = "Wild Growth：在7秒内治疗目标及其队伍，开始时更强：队伍里不止一个人受伤时使用。",
    ["8f8a34a"] = "Aspect of the Hawk，驯服宠物（职业任务：Tame Beast、Call Pet、Feed Pet、Revive Pet）",
    ["2b3db50"] = "Auto Shot 会自动开始：每次射击前站定半秒，让怪物靠近。如果它追上你就用 Raptor Strike。8码以内远程射击无效。",
    ["9329f10"] = "开场时加上 Serpent Sting，只对能活得久的怪物使用：如果它几秒就死了，伤害就浪费了。",
    ["d2b7bf1"] = "拉怪前 Hunter's Mark，然后 Serpent Sting。有法力时用 Arcane Shot。",
    ["85f72cd"] = "核心是 Auto Shot，有法力时加 Arcane Shot。拉怪前 Hunter's Mark，然后以 Serpent Sting 开场。怪物向你冲来时 Concussive Shot 减速它；如果它追上你就用 Raptor Strike。",
    ["71067ff"] = "你有宠物：先让它冲上去几秒，然后 Serpent Sting。始终保持 Aspect of the Hawk 并给宠物喂食。怪物转向你时用 Concussive Shot，最后手段才用 Raptor Strike。",
    ["bb6f64b"] = "Rapid Fire（15秒内攻击速度+40%）不放进输出循环：留给需要它的那次拉怪。",
    ["ebe54cf"] = "核心是每次冷却好就用 Aimed Shot（2秒施法，6秒冷却与 Multi-Shot 共享），空档用 Auto Shot。拉怪前 Hunter's Mark，宠物先上，然后 Serpent Sting。有法力时用 Arcane Shot。如果怪物追上你：Disengage。有多个怪物时：用 Multi-Shot 代替 Aimed Shot。",
    ["c943332"] = "核心是猎鹰（Summon Hawk）：每只猎鹰持续18秒，可以同时存在两只；两只中有一只消失时召唤新的。然后冷却好时用 Aimed Shot，空档用 Auto Shot。Arcane Shot 与猎鹰共用冷却，所以放在它们之后。其余同前。",
    ["ab9f050"] = "加上 Intimidation：如果怪物转向你，它会击晕并给宠物威胁；没准备好时用 Disengage。有多个怪物时：先 Explosive Trap，然后在 Aimed Shot 的冷却期用 Multi-Shot。",
    ["bf06335"] = "Bestial Wrath（2分钟）和 Volley 不放进输出循环：在危险的拉怪或大群怪时手动使用。从42级起几乎所有点数都投入 Marksmanship：输出循环不变。",
    ["e096af7"] = "Beast Mastery 从远处射击：远程武器DPS最重要，然后是敏捷。近战武器只因它的属性而需要。",
    ["b35c3c9"] = "核心是每次冷却好就用 Aimed Shot，空档用 Auto Shot。在宠物抢先之后，第一击必须是最强的：有 Rapid Killing 待命时就是 Aimed Shot。拉怪前 Hunter's Mark 并让宠物先上；对每个怪物用 Serpent Sting，因为如果它带着 Serpent Sting 死去，你20秒内的下一击最多多造成20%伤害。有法力时用 Arcane Shot。如果怪物追上你：Disengage。有多个怪物时：用 Multi-Shot 代替 Aimed Shot。",
    ["cf4e14e"] = "拉怪前除了 Hunter's Mark 还要 Trueshot Aura。",
    ["51e16cf"] = "Sniper Shot 是你最强的射击：4秒施法，15秒冷却，最远45码，并且在10秒内你接下来的三次射击会远10码。当你有时间施法时把它作为宠物抢先后的第一击，最好有 Rapid Killing 待命；否则用 Aimed Shot。有多个怪物时：先 Explosive Trap，然后在 Aimed Shot 的冷却期用 Multi-Shot。",
    ["c8aaa16"] = "核心是猎鹰（Summon Hawk）：两只中每消失一只就召唤一只新的。然后冷却好时用 Aimed Shot，空档用 Auto Shot；有时间时第一击用 Sniper Shot。Arcane Shot 放在猎鹰之后。",
    ["1fe9ee6"] = "Marksmanship 从远处射击：远程武器DPS重要（其他条件相同，更慢但单次伤害大的更好，因为 Aimed Shot 基于一次武器攻击）以及敏捷。有 Careful Aim 时，智力除了法力外也算攻击强度。近战武器只因它的属性而需要。",
    ["184fc61"] = "Survival 在两个地方战斗。远程：每次冷却好就用 Multi-Shot（它是瞬发，与 Aimed Shot 共享冷却，所以你几乎不用 Aimed Shot），加上 Serpent Sting、Arcane Shot 和 Auto Shot。近战：Immolation Trap，然后 Raptor Strike（瞬发，冷却6秒）和闪避后的 Mongoose Bite。拉怪前 Hunter's Mark，宠物先进场。",
    ["d85837a"] = "Strider Kick：一记造成武器全额伤害的踢击，让你3秒内加速30%：它是结束近战并让你回到远程的按键。近战时先 Immolation Trap，可用时 Mongoose Bite，然后 Raptor Strike。远程时冷却好就 Multi-Shot，Serpent Sting，Arcane Shot，Auto Shot。有多个怪物时 Explosive Trap 取代 Immolation Trap，因为所有陷阱共用一个冷却。",
    ["e7233e1"] = "有 Lacerating Strikes 时，每次 Mongoose Bite 会留下一个流血，伤害为该击伤害的40%，持续21秒。",
    ["10bfe36"] = "Survival 会射击，但也用近战武器攻击（Raptor Strike 和 Strider Kick 基于它的伤害）：慢速双手武器有帮助。然后敏捷重要。从49级起，Careful Aim 让智力也能当作攻击强度。",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, 传送到两座主城（以及 Arcane 和 Fire 的 Arcane Blast）",
    ["ad986c1"] = "Conjure Mana Agate（第一颗法力宝石）",
    ["3e67dd9"] = "Ice Armor；职业任务（魔杖 Ice Fury）",
    ["3ddbf7c"] = "Frostfire Bolt，第一批传送门",
    ["3d9e7fb"] = "始终保持 Arcane Intellect 和一个护甲法术（目前是 Frost Armor）。每次施放消耗法力的法术后，法力回复会暂停5秒：快死的怪物不值得一次完整施法。5级前后弄一把魔杖（附魔师会给你做 Lesser Magic Wand，13级起是 Greater Magic Wand）：在有天赋之前，它造成的伤害可以和你的法术一样多甚至更多，而且不耗法力。",
    ["2991425"] = "用 Frostbolt 在最大射程开场，让怪物减速着到来。它靠近时继续施法，然后 Fire Blast 收尾，剩下的用魔杖。",
    ["5d6b9a7"] = "Frost Nova 冻结你周围的一切：受到伤害会打破冰冻，所以你可以后退并继续施法。如果怪物到了近战：Frost Nova 然后后退。",
    ["11f2d67"] = "有 Missile Barrage 时：从远处用 Frostbolt（Arcane 和 Frost）或 Fireball（Fire）开场，继续施法，触发时施放 Arcane Missiles：它们变成一次免费的齐射。Missile Barrage 是升级时最能省法力的天赋。",
    ["b985201"] = "Evocation 是8秒的引导，能还给你大部分法力。跑动时冷却好就用 Blink，能让你大约快五分之一到达。炉石更适合用于任务区域，因为传送已经把你带到主城。",
    ["a601e53"] = "Arcane Blast：每次施放给你相当于你智力12%的法术伤害，最多4层，持续18秒；每层使下一次施放消耗增加100%。从远处 Frostbolt，然后 Arcane Blast 一到三次，直到 Missile Barrage 触发，再 Arcane Missiles。让层数自然消失，不要叠到四层。把 Clear Casting 用在已叠层的 Arcane Blast 上。近战时：Frost Nova 然后后退。Fire Blast 收尾，再用魔杖。",
    ["e55eb73"] = "Arcane Wrath：冷却6秒的重击（额外伤害相当于你最大法力的5%）。从远处 Frostbolt，然后 Arcane Wrath，Arcane Blast 一到三次直到 Missile Barrage 和 Arcane Missiles；它靠近时 Frost Nova，再来 Arcane Wrath，然后 Fire Blast 和魔杖击杀。让层数自然消失，否则不断上升的消耗会把你掏空；Clear Casting 只用在已叠层的 Arcane Blast 或 Arcane Wrath 上，绝不要用在便宜的法术上。",
    ["65a5bf0"] = "Presence of Mind：你的下一个施法时间低于10秒的法术变为瞬发。",
    ["c51b464"] = "Arcane Power：15秒内伤害+30%，代价是法力消耗+30%。",
    ["dfc4101"] = "从远处用 Pyroblast 或 Frostbolt 开场，然后 Arcane Wrath。Arcane Blast 一到三次直到 Missile Barrage，然后是飞弹。从58级起冷却好就用 Fire Blast，Heating Up 达到3层时用 Pyroblast。",
    ["9226a40"] = "对每个专精，法术强度排第一，因为你的法术随它大幅成长。智力提高法力和少许暴击；精神减少喝水的停顿，对 Arcane 来说很重要，因为它法力消耗很快。",
    ["ebbbb02"] = "从远处 Fireball。一两次 Arcane Blast 直到 Missile Barrage 触发，然后是飞弹。冷却好就 Fire Blast。血量少的怪物不需要保持距离：让它打你几下，低于15%时用魔杖收掉。",
    ["9e5f918"] = "即使怪物贴在身上，Scorch 也能填补空档。",
    ["ab79a6b"] = "从远处用 Frostfire Bolt 开场，然后一两次 Arcane Blast 直到 Missile Barrage 触发，再是飞弹。冷却好就 Fire Blast，用 Scorch 填补空档，最后15%用魔杖。",
    ["bece8ec"] = "Pyroblast 与 Heating Up：Fireball、Frostfire Bolt、Fire Blast 或 Scorch 的每次非周期性暴击，会让你下一个 Pyroblast 加快四分之一，最多3层，而 Fire Blast 每次造成伤害都会增加一层。当 Heating Up 达到3层时施放 Pyroblast。",
    ["196edb9"] = "对每个专精，法术强度排第一。智力提高法力和少许暴击；精神减少喝水的停顿。",
    ["38bc29a"] = "Frost 从 Precision 开始：两点就能让你对同等级怪物的命中率达到100%。",
    ["c690916"] = "Frostbite：你的冰霜效果有15%的几率冻结目标5秒。Ice Lance（27级起）：对被冻结的目标多造成300%伤害，冷却8秒，与 Fire Blast 共享。",
    ["1f1ed9a"] = "从远处 Frostbolt，怪物到来时继续施法。当 Frostbite 冻结目标时：一个 Frostbolt 紧跟 Ice Lance；如果 Ice Lance 没准备好，就用 Cone of Cold。近战时：Frost Nova 然后后退，再对被冻结的怪物用 Frostbolt 和 Ice Lance。Missile Barrage：施放飞弹，或者如果这个怪物快死了就留给下一个。对没被冻结的低血怪物用 Fire Blast 或魔杖。",
    ["2e43c7c"] = "有 Fingers of Frost 时，你接下来的两个法术会把目标视为被冻结：第一个用在 Frostbolt 上，第二个用在带 Ice Lance 的 Frostbolt 上（如果 Ice Lance 还没好，就用 Cone of Cold）。它的强项在30多级：Shatter 之后，被冻结的目标会承受你最重的打击。",
    ["cecd125"] = "先上 Ice Barrier，一分钟结束时再放一次：除了护盾，它还让你一分钟内的冰霜伤害增加15%。",
    ["959453a"] = "Winter's Chill：Frostbolt 和 Ice Lance 把它叠加在目标上，最多5层，下一个 Cone of Cold 每层多造成20%伤害。",
    ["5a9d3eb"] = "Redemption（职业任务）",
    ["3d343ad"] = "Seal of Command（Retribution 天赋）, Seal of Justice",
    ["32b558d"] = "双专精和坐骑",
    ["38d0905"] = "拉怪前 Blessing of Might 和 Devotion Aura。然后三步：Seal of Righteousness，向怪物跑去时用 Judgment，Holy Strike。之后，Judgment 和 Holy Strike 每次冷却好就用，只在圣印快结束时才刷新（Judgment 不再消耗圣印，并且不占公共冷却）。法力也是你的治疗：如果下一击能杀死怪物，就跳过这个按键。如果战斗结束时法力有剩余，用 Holy Light 把它变成生命。危险时：先给自己 Divine Protection，然后治疗。",
    ["f580de7"] = "当你对付多个敌人或法力有余时用 Consecration：它比 Judgment 和 Holy Strike 加起来还贵，需要8秒才能造成全部伤害。对每个亡灵或恶魔用 Exorcism，甚至可以30码外使用。",
    ["2ea2c89"] = "加上 Hammer of Wrath：它能收掉生命值低于20%的敌人。",
    ["c8d4778"] = "Retribution 和 Protection 在同一棵树里开始，天赋几乎相同。你可以选 Benediction 代替 Deflection（5%招架）：所有瞬发技能少消耗10%法力，Consecration 也更容易负担。",
    ["a81d5b1"] = "有 Seal of Command 时：Blessing of Kings 或 Might 和 Retribution Aura。对活得久的怪物：先用 Seal of the Crusader 的 Judgment（怪物受到更多神圣伤害），然后如果你有慢速武器就换成 Seal of Command；用快速武器或法术伤害很多时 Seal of Righteousness 更好。然后每次冷却好就 Judgment 和 Holy Strike。窍门：Seal of Command 的 Judgment 对被击晕的目标几乎翻倍，所以先 Hammer of Justice 再 Judgment。",
    ["733e5e6"] = "Sacred Arbiter：Holy Strike 的伤害提高20%，并刷新目标身上的每个 Judgment，包括其他圣骑士的。",
    ["a01f90a"] = "Champion of the Light 把你最多60%的智力转化为法术伤害：带法术强度的装备会变得更好。40级的 Unsealed Wrath：攻击会保留当前圣印的副本（最多3个），换圣印又变得划算了。",
    ["5f3698b"] = "武器是最重要的：理想情况下带法术强度且伤害高。有 Seal of Command 时，慢而重的武器最好（Holy Strike 和圣印造成更多伤害）。其余属性先看力量或攻击强度，然后耐力，再是法术强度。",
    ["4c063de"] = "神圣系从惩戒系开始：前12点（到21级）投入惩戒，获得更高的法力效率和正义追击（Pursuit of Justice）。20级之前你的治疗是 Holy Light、Lay on Hands 和 Blessing of Protection：单人做任务时，像输出圣骑士一样使用 Seal of Righteousness、Judgment 和 Holy Strike，不要浪费法力。",
    ["e1a4083"] = "有了 Flash of Light 你就有两种治疗：Holy Light 又慢又强，适合需要大量生命值且有时间的时候；Flash of Light 又快又省法力，适合小而持续的伤害。选对治疗就是全部工作：选错会白白烧法力。20级起还有 Consecration、Exorcism 和 Blessing of Kings。",
    ["42143bb"] = "22级起点数投入神圣：Spiritual Focus（受击时施法被延迟得更少），然后是 Reverence（施法时仍保留一部分法力回复）和 Healing Light（提高 Holy Light、Flash of Light 和 Holy Shock 的治疗量）。",
    ["a1c4391"] = "如何治疗：坦克受到持续伤害时用 Flash of Light 或 Holy Light；突发伤害用 Holy Shock；紧急情况用 Lay on Hands（会耗尽全部法力）。Blessing of Protection 用在受到物理伤害的队友身上，不要用在坦克身上：坦克免疫后敌人会转向其他人。",
    ["e98c82f"] = "Illumination：Flash of Light、Holy Light 或 Holy Shock 的暴击治疗可以返还法力（基础消耗的一半），所以智力和暴击很重要。37级起把 Oath of Light 放在主要目标身上；38级起有 Infusion of Light：Holy Shock 或 Flash of Light 的暴击治疗会让下一个 Holy Light 更快。",
    ["3bb92dd"] = "40级获得双天赋专精（把惩戒留作单人任务用的第二专精）和板甲。42级起有 Holy Shock：冷却10秒的瞬发治疗，或对敌人造成神圣伤害。45级起有 Divine Favor：下一次治疗必定暴击（冷却2分钟），用于坦克有危险时。47级起 Holy Power 提高 Holy Shock 和 Holy Strike 的暴击几率。",
    ["31364c3"] = "Light's Vigil：给队友施加30秒的效果；对同一目标使用 Holy Shock 会触发它，同时治疗队伍，并且不会让 Holy Shock 进入冷却。消耗很大，每个队伍只能有一个：留给多名玩家受伤的情况。对敌人使用会返还75%的法力。最后的点数（56级起）投入 Divine Intellect。",
    ["7fda0df"] = "对神圣系来说，首先是治疗强度，其次是智力（更多法力和更多暴击，暴击通过 Illumination 返还法力），然后是每5秒回复法力和精神（有了 Reverence，施法时仍保留一部分回复）。武器看的是属性而不是伤害：带治疗和精神的锤胜过 DPS 更高的武器。40级前穿锁甲，之后穿板甲，但属性合适的布甲比没有属性的锁甲更有价值。",
    ["a531e3f"] = "Seal of Fury 是坦克的圣印：每次攻击造成额外神圣伤害，持盾时你获得相当于该伤害一半的吸收。它的 Judgment 让你从10码外嘲讽3秒。Righteous Fury 让你的所有威胁提高33%。从22级起你转入 Protection 天赋树，在 Pursuit of Justice 之后。",
    ["8279baa"] = "Blessing of Kings、Retribution Aura 和 Righteous Fury 保持开启。始终保持 Seal of Fury。向怪物跑去时用 Judgment 来嘲讽。法力允许时，一进入近战就放 Consecration。然后每次冷却好就 Holy Strike，对亡灵和恶魔用 Exorcism。聚集最多四个敌人，用 Consecration 把它们全部烧掉。",
    ["34e2900"] = "Shield Specialization：一次格挡返还4%的最大法力，最多每3秒一次：这是你法力的很大一部分。",
    ["cc3ac76"] = "Templar's Bulwark：一个护盾，8秒内吸收相当于你全部生命的伤害，但会给你 Forbearance 一分钟。从37级起 Swift Judgement：圣印的 Judgment 会自动触发，冷却1分钟，所以你多了一次嘲讽。",
    ["be55413"] = "Holy Shield：10秒内你格挡更频繁，最多4次格挡造成神圣伤害。Reckoning（43级起）可在格挡或受到暴击后给你一次额外攻击。",
    ["e76d8e9"] = "对 Protection，法术强度排第一（Seal of Fury、Holy Shield 和 Consecration 造成神圣伤害），然后是力量和耐力。武器越快越好：Seal of Fury 每次攻击都会触发。带法术强度的武器伤害低一点也值得。",
    ["05e5db7"] = "Shadow Word: Pain；简短的职业任务（一件长袍）",
    ["c95888a"] = "Mind Blast, Resurrection；种族任务教你第一个只属于你种族的技能",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead；第二个种族技能",
    ["71b2a72"] = "拉怪前给自己上 Fortitude。用 Smite 开场，给目标上 Shadow Word: Pain，然后用魔杖收尾，魔杖不耗法力，开始时造成你伤害的很大一部分（使用前站定半秒）。如果怪物追上你，先 Power Word: Shield。最重要的是有一把好魔杖：每次找到更好的就换掉。",
    ["e023128"] = "Mind Blast 是冷却短的强力一击。前七个天赋点对所有专精都一样：Wand Specialization（10-11）和 Spirit Tap（12-16）。有 Spirit Tap 时，每次击杀会给经验的怪物，都会让你的精神翻倍15秒，期间一半的法力回复在施法时继续：喝水的停顿更少。",
    ["8df287d"] = "Inner Fire：额外护甲，每次受到攻击消耗一层。让它和 Fortitude 一直在你身上，结束时重新施放。",
    ["bebe913"] = "Psychic Scream 让附近的敌人逃跑，但要小心：它们可能带回其他怪物。",
    ["ffa87bf"] = "导师今天教你的比任何其他等级都多：Holy Fire（开场慢但强，还会持续灼烧）、Flash Heal（快但贵）、Devouring Plague（持续伤害并治疗你）等等。",
    ["084f80e"] = "Shadow 是我们推荐的单人升级专精：点数投入 Shadow Word: Pain、Mind Blast 和 Mind Flay，让怪物更快死亡。",
    ["f33a503"] = "如果怪物追上你，给自己上 Shield。用 Mind Blast 开场，然后 Shadow Word: Pain。从27级起还有 Devouring Plague 和 Mind Flay，并在 Shadow Word: Pain 之后加上 Vampiric Embrace，让你的暗影伤害治疗你。然后用魔杖收尾。法力低时跳过 Devouring Plague 和 Mind Flay。",
    ["496ef3d"] = "Shadow Word: Death 是突发伤害，但如果目标存活，你会承受你最大生命的30%：留给最后一击。",
    ["edd0d02"] = "Shadowform：战斗时保持 Shadowform（暗影伤害+10%，暗影法术法力消耗减半，物理伤害-15%，但不能施放治疗：治疗前先退出）。用 Mind Blast 开场，然后 Shadow Word: Pain、Vampiric Embrace、Devouring Plague 和 Mind Flay。当再多一击就能杀死怪物时：Shadow Word: Death，或把最后一点留给魔杖。如果怪物追上你，给自己上 Shield。",
    ["b912dce"] = "对 Shadow，法术强度排第一（暗影强度也行：你几乎所有伤害都是暗影），然后是暴击和命中（Hit）。魔杖非常重要：开始时它造成很大一部分伤害。",
    ["8e3f775"] = "Discipline 是我们推荐的单人游玩治疗专精：20级起 Power in Light 给 Smite 增加伤害。",
    ["916c9c2"] = "从远处用 Holy Fire 开场，怪物到来时用 Smite，然后 Mind Blast、Shadow Word: Pain 和魔杖。如果战斗不顺：给自己上 Shield，然后治疗：需要快就 Flash Heal，有时间就 Heal。",
    ["a80f7e5"] = "Penance：一连串神圣攻击，伤害敌人或治疗盟友，冷却12秒，第一击立刻打出。",
    ["037a666"] = "先给自己上 Shield。从远处用 Holy Fire 开场。怪物走来时 Smite，然后对同一目标 Penance，因为 Power in Light 让它打得更重。然后 Mind Blast 和 Shadow Word: Pain。收尾时，如果一击能杀死就 Shadow Word: Death，否则用魔杖。每次 Weakened Soul 消失，你就可以再次保护自己。",
    ["9d0affc"] = "Power Infusion：15秒内伤害和治疗+20%，对自己或朋友：每次冷却好就在开场前对自己施放。60级的 Inner Focus 用于紧急情况：下一个法术免费。",
    ["8e7cd8d"] = "对 Discipline 和 Holy 寻找治疗强度和法力回复，然后是智力和精神。选具有这些相同属性的武器：是法杖还是带副手的单手武器都无所谓。",
    ["c5c1351"] = "拉怪前给自己上 Shield 和 Renew。然后用 Holy Fire 开场，怪物到来时 Smite，Mind Blast 和 Shadow Word: Pain。能杀死时用 Shadow Word: Death 收尾，否则用魔杖。",
    ["575bdd0"] = "Holy Nova 伤害附近的每个敌人并治疗队伍：它很耗法力，所以在多个敌人贴身时使用，或在它免费时使用（43级起的 Searing Light：Holy Fire 可以让下一个 Holy Nova 免费）。",
    ["6953353"] = "拉怪前给自己上 Shield、Renew 和 Prayer of Mending（目标下次受到伤害时治疗，然后跳到队伍中的另一人，冷却10秒）。",
    ["a5c9096"] = "对 Holy 寻找治疗强度和法力回复，然后是智力和精神。选具有这些相同属性的武器。",
    ["aa71e89"] = "Backstab（需要匕首，只能从背后）, Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap；职业任务（Blade of Cunning）",
    ["3a2246d"] = "Ambush（需要匕首）, Poised（被动）",
    ["8abd601"] = "Rupture；毒药任务：Instant Poison 和 Crippling Poison",
    ["6c840ea"] = "Shank（Forever 的新技能）",
    ["f3d428e"] = "Mutilate（Assassination 天赋）",
    ["3e307c7"] = "Death Mark（Subtlety 天赋）, Slice and Dice 2级",
    ["f14c847"] = "Shank 2级",
    ["a554ba3"] = "走到怪物面前，有连击点时用 Sinister Strike，然后 Eviscerate：点数越多，打击越强。Stealth 暂时可以留在动作条上。如果战斗不顺：用 Evasion 和 Gouge 打断施法或争取几秒钟。",
    ["44b2b7e"] = "Slice and Dice（终结技：你的攻击快20%，点数越多持续越久）、Sprint（15秒内快50%，不会打破 Stealth）和 Sap，用来在开战前把一个人形生物移出战斗。",
    ["665b56f"] = "Rupture：点数越多，流血越久。有毒药任务时，Instant Poison 和 Crippling Poison。",
    ["d06b2e0"] = "Shank：不会未命中的副手攻击；第一级消耗5点能量，返还15点，10秒冷却。从26级起从潜行用 Cheap Shot：击晕4秒并给2个点。",
    ["6974c7f"] = "Combat 是决斗者：用你喜欢的武器近战，适用于任何武器，开始时不需要潜行。它是我们推荐的单人升级专精。",
    ["cea5a19"] = "Riposte：你招架之后亮起，造成一倍半的武器伤害，缴械怪物6秒，只消耗10点能量，冷却6秒。",
    ["5288c4d"] = "双手武器都涂 Instant Poison。艰难的战斗从潜行用 Cheap Shot，否则直接 Sinister Strike。招架后立刻 Riposte。Shank 冷却期间用 Sinister Strike 攒点：前五个点给 Slice and Dice，接下来五个给 Eviscerate。",
    ["869d1bf"] = "有两个怪物贴身时：Blade Flurry（每2分钟一次，15秒内你攻击快20%，每次攻击还会打到附近的第二个目标）。",
    ["9fb5eb8"] = "对危险的怪物用 Adrenaline Rush（每5分钟一次：15秒内能量回复快一倍）。",
    ["f8cc28b"] = "在大 Eviscerate 之前用 Cold Blood。",
    ["625324b"] = "带敏捷的皮甲：这就是你要的。命中（Hit）、暴击、攻击强度和耐力都有用。Combat 可以使用任何类型的武器，因为 Hack and Slash 对每种武器都给加成：剑和斧、匕首和拳套、锤。",
    ["d01cb25"] = "Assassination 是用毒的：毒药和终结技越来越强，40级时 Mutilate 到来。",
    ["9eb3d72"] = "双手武器都涂 Instant Poison。从潜行用 Garrote 或 Cheap Shot 开场。用 Sinister Strike 攒点，Shank 冷却好就用。Slice and Dice，然后 Eviscerate；把 Cold Blood 留给大 Eviscerate。",
    ["33aceb3"] = "Venom：每次 Shank 之后6秒内，你的毒药伤害高30%，触发率高20%。Shank 冷却好就用。",
    ["88ede56"] = "Mutilate 攒点：用双手武器攻击，对中毒目标伤害高20%，并给2个点。需要两把匕首。Slice and Dice，为 Venom 在冷却好时 Shank，然后 Eviscerate；大 Eviscerate 时用 Cold Blood。",
    ["20500ff"] = "带敏捷的皮甲。Assassination 需要匕首来使用 Backstab、Ambush 和 Mutilate。命中（Hit）、暴击、攻击强度和耐力都有用。",
    ["5259278"] = "Subtlety 是伏击者：每场战斗都手持匕首从暗处开始。",
    ["64f4a07"] = "主手拿匕首，双手武器都涂 Instant Poison。绕到怪物背后，Premeditation，然后 Ambush，然后 Ghostly Strike，然后 Garrote。其余用 Sinister Strike 攒点；为了能量，Shank 冷却好就用；Eviscerate 收尾。",
    ["37c1365"] = "Hemorrhage 代替 Sinister Strike 攒点。",
    ["c0f22d5"] = "Hemorrhage 和 Shank 攒点，有 Boot Knife 时每个 Shank 算两个。Death Mark 储存6秒伤害：当怪物活得够久时，把一整套点数花在它上面，然后 Eviscerate 收尾。如果战斗不顺，Preparation 会重置 Premeditation、Ghostly Strike 和你的其他冷却。",
    ["a993dd2"] = "带敏捷的皮甲。Subtlety 主手拿匕首（Ambush 和 Backstab 要求如此）。命中（Hit）、暴击、攻击强度和耐力都有用。",
    ["abbb551"] = "Earth Shock；大地图腾任务：Stoneskin Totem",
    ["8e8845b"] = "火焰图腾任务：Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem（水图腾任务）, Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation（需要 Ankh）, Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem；空气图腾任务（风暴武器）",
    ["b821239"] = "Chain Heal，锁甲",
    ["d6b5209"] = "Rockbiter Weapon 留在武器上，从8级起拉怪前给自己上 Lightning Shield。用 Lightning Bolt 开场，怪物一到就用 Earth Shock，它是瞬发的；对付施法者，留着震击来打断它的施法。怪物贴身后，由近战攻击收掉它。如果又来一个怪物，放 Earthbind Totem：它会减速怪物，让你能风筝。战斗结束后如果受伤，Healing Wave。",
    ["fa734a3"] = "每个专精都有明确的定位：Enhancement 用大武器、图腾和震击近战；Elemental 用 Lightning Bolt、Chain Lightning 和 Fire Nova 在远处战斗；Restoration 负责治疗，待在队伍或副本里，不适合单人做任务。如果法力耗尽，Enhancement 还能继续打（击杀时间更长），Elemental 则更吃亏。",
    ["b74be3c"] = "Flame Shock 立刻造成火焰伤害，然后灼烧12秒。Flametongue Weapon 给每次攻击增加火焰伤害；Searing Totem 是一个小炮塔，会射击附近的敌人。",
    ["35c7293"] = "Enhancement 是我们推荐做任务的专精。它有自己的弱点：差的武器会大幅降低伤害，开始时的法力消耗很重，同时面对许多敌人时会吃力。",
    ["028a6b7"] = "Stormstrike 每8秒立刻造成武器的全额伤害，目标会多承受你下一个 Lightning Bolt、Chain Lightning 或 Earth Shock 的20%伤害。",
    ["a94041d"] = "Stormstrike 每次冷却好就用，之后紧接着 Earth Shock（Stormstrike 的攻击让震击更强）。Rockbiter Weapon 始终在武器上，Lightning Shield 在自己身上。拉怪前 Strength of Earth 和 Mana Spring，法力允许的话 Searing Totem 或 Magma Totem。用1级的 Lightning Bolt（最便宜）开场，其余由普通攻击完成。只有当怪物在你火焰图腾范围内且你还有法力时才用 Fire Nova。击杀后 Healing Wave，法力低就喝水。",
    ["18a8896"] = "把 Windfury Weapon 放到武器上代替 Rockbiter：每次攻击有20%几率额外打出两次攻击，这是 Enhancement 的大头。如果闪避或招架重置了 Stormstrike，立刻再按一次。Windfury Totem，对施法者用 Grounding Totem 取代它。",
    ["f3777c4"] = "Maelstrom Weapon：你的攻击最多积累5层，每层让下一个 Lightning Bolt 更快更便宜：5层时施放最高等级的 Lightning Bolt。从46级起，Water Shield 取代 Lightning Shield（只能有一个）。",
    ["022a55d"] = "对 Enhancement，武器最重要：理想的是速度3.3到3.8之间的慢速双手武器。然后是力量和攻击强度，智力紧随其后，因为它为 Mental Dexterity 和法力提供支持。",
    ["4540d89"] = "Earthbound：放置 Earthbind Totem 时，附近的敌人会被困住5秒。",
    ["bcd1d77"] = "拉怪前 Mana Spring Totem 和一个火焰图腾（对一个怪物用 Searing，对多个怪物用 Magma），给自己上 Lightning Shield。在射程边缘用 Lightning Bolt 开场，给目标上 Flame Shock，然后继续 Lightning Bolt。有三个或更多怪物时，Fire Nova 每次冷却好就用。Earth Shock 打断施法者并把它引向你。怪物靠近时放 Earthbind Totem。结束时治疗并喝水。",
    ["13a3832"] = "面对单个怪物：Searing Totem，从远处用 Lightning Bolt 开场，Flame Shock，继续 Lightning Bolt。面对三个或更多：Magma Totem，用 Chain Lightning 开场，对其中一个上 Flame Shock，然后每次冷却好就 Chain Lightning 和 Fire Nova，中间穿插 Lightning Bolt。",
    ["2c3ba7a"] = "Lightning Mastery（持续15秒，冷却3分钟）：15秒内 Lightning Bolt 施放更快，Chain Lightning 无视自己的冷却。用在精英或大群怪上，否则每次冷却好就用。",
    ["b56c9ed"] = "Water Shield 取代你身上的 Lightning Shield。",
    ["4688073"] = "对 Elemental 寻找法术强度，智力主要为了法力。40级起可以穿锁甲。",
    ["b4ca62b"] = "拉怪前 Water Shield、Mana Spring Totem 和队伍能用的图腾。有人受伤时，Healing Wave 是主力。Lesser Healing Wave 施法1.5秒，按法力算治疗较少：留给时间重要的时刻。当全队没法力时用 Mana Tide Totem（12秒，冷却5分钟）。没人有危险时增加伤害：对目标用 Lightning Bolt，对一群怪用 Fire Nova。结束时喝水。",
    ["42937c0"] = "Nature's Swiftness（每3分钟）：你的下一个自然法术是瞬发，所以可以给快死的朋友一个瞬发的 Healing Wave。如果有玩家在近战，用 Windfury Totem。",
    ["9b2d19c"] = "Riptide：持续治疗，冷却12秒，对 Riptide 的目标施放的 Chain Heal 强25%。Chain Heal 治疗目标和另外两个盟友，所以能覆盖分散在队伍中的伤害。",
    ["a86408d"] = "对 Restoration 寻找治疗强度，智力主要为了法力。40级起可以穿锁甲。",
    ["c86a1be"] = "Voidwalker（职业任务）, Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus 和 Incubus（职业任务）, Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter（职业任务）, Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed（任务）",
    ["1c5b068"] = "恶魔先上，然后 Bane of Agony 和 Corruption；只有最难缠的怪物才上 Immolate，因为恶魔会拉住它们。顺序很重要，因为伤害会吸引注意：Agony 最初的跳伤很小，所以恶魔会拉住怪物，直到新的 Immolate 打得足够重，让它转向你。保持 Demon Skin，对快死的怪物跳过 DOT，并且在它还在造成伤害时不要刷新 Agony。在你有魔杖之前，由 Shadow Bolt 完成收尾；之后弄一把魔杖：每一发都是为下一次拉怪省下的法力。",
    ["ea42414"] = "Drain Soul 是你获取 Soul Shard 的主要来源：一个不平凡的怪物死于它的吸取时，总会给一个。碎片少时用它来收掉击杀。Healthstone、Soul Stone 以及 Voidwalker、Succubus 和 Felhunter 的召唤都需要碎片。",
    ["72f97d5"] = "Drain Life 改变你看屏幕的方式：如果蓝条低而你的生命良好，用 Life Tap；如果你的生命真的下降了，对怪物用 Drain Life。这样几乎所有的空档都消失了。",
    ["51205f3"] = "用 Demon Armor 代替 Demon Skin。有 Ritual of Summoning，你和两个同伴可以把还很远的队友召唤过来。一个 Fear 能给你几秒钟的免费时间来包扎。",
    ["9d83c05"] = "如果你单人游玩，Affliction 是首选：命中和瞬发的 Corruption 来得很早。Curse of the Elements 放在 Agony 旁边。从25级起，Nightfall 可以由 Corruption、Drain Life 或 Drain Soul 的伤害触发，触发后的 Shadow Bolt 没有施法时间。你可以在30级稍前拿吸取天赋，并在每场战斗中依靠 Drain Life。",
    ["04f03c2"] = "Siphon Life：30秒内每3秒跳一次伤，所以10秒就死的怪物只吃到三分之一。留给长时间的战斗。",
    ["703c37f"] = "Demonic Sacrifice：你牺牲 Felhunter，两小时内每4秒恢复你总生命的3%；召唤恶魔会取消它，所以从这里开始你做任务几乎不带宠物。",
    ["2dbcea6"] = "Wrack：你引导6秒，造成暗影伤害，在持续期间，你施加在该目标上的其他暗影 DOT 伤害提高10%。",
    ["edb7e47"] = "选择带法术强度的武器，因为你几乎不会用它们来攻击。开始时魔杖升级胜过几乎所有其他东西；之后法术强度排第一。耐力是额外的生命，可以用 Life Tap 转成法力，智力是更大的法力池，精神让每次 Life Tap 回得更多。",
    ["1c3a6a3"] = "如果你更喜欢看恶魔干活，选 Demonology：25级起配合 Demonic Brand。从25级起，Searing Pain 在目标上留下一个标记10秒，最多你恶魔的前六次攻击造成额外伤害：用一个快速的 Searing Pain 打在恶魔正在战斗的目标上刷新它，并用 DOT 和魔杖填补空档。",
    ["00d4a86"] = "Soul Link：对你的每次直接攻击的30%转给恶魔，你们两个造成的伤害多3%。换恶魔时会失效：每次都要重新施放。",
    ["a3cee7a"] = "Demonic Pact：牺牲在换恶魔后依然有效，除非你召唤的正是你牺牲的那只。在副本里牺牲 Imp（暗影伤害多15%）；单人任务时牺牲 Felhunter 以获得它的治疗，并与 Voidwalker、Succubus 或 Incubus 并肩作战。从27级起你也可以用 Affliction 升级并切换专精：你有 Demonic Brand 三个等级所需的点数。",
    ["545f2c9"] = "Destruction 从10级起可玩，但在39和40级会强得多，而且比另外两个专精更多时间站着施法：也可以以后再选。",
    ["0b5d29c"] = "Shadowburn：一次瞬发攻击，消耗一个碎片，如果一个不平凡的目标在8秒内死亡就返还碎片。",
    ["124afde"] = "开场改变了：从最大距离用 Shadow Bolt，在箭矢还在飞行时上 Immolate。这样怪物会冲向你而不是恶魔，所以选择你能快速结束的战斗。Shadowburn 收掉怪物；最好把 Conflagrate 留到你的 Immolate 快结束时。",
    ["07ea333"] = "有 Shadow and Flame 时，Conflagrate 让你的暗影伤害提高20%，Shadowburn 让你的火焰伤害提高20%；Conflagrate 不再消耗 Immolate，Shadowburn 总是返还碎片。从39级起没有理由再保留它们。",
    ["609f38c"] = "Incinerate 对已经被你的 Immolate 灼烧的一切多造成25%伤害。",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor（职业任务）, Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery（向导师学习）",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation；你可以使用双武器",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept（职业任务）",
    ["b289adb"] = "板甲和坐骑",
    ["2debde0"] = "拉怪前 Battle Shout，Charge，对活得久的怪物用 Rend，然后让普通攻击积累怒气。只在有不需要的怒气时才用 Heroic Strike：它取代一次普通攻击，而那次攻击不给怒气。有多个怪物时用 Thunder Clap；不要在快死的怪物身上花怒气。",
    ["f98c5d6"] = "两次拉怪之间用 Bloodrage：它消耗一点生命，立刻给10点怒气，10秒后再给10点。永远不要在没有怒气的情况下开始战斗。",
    ["970305a"] = "Victory Rush 每次亮起就用：在一次给经验的击杀之后你有20秒，它造成伤害并治疗你10%，冷却30秒，不消耗怒气。",
    ["a60b4a3"] = "从14级起 Revenge 是你的主要攻击：每次亮起就用（在格挡、闪避或招架之后）。换成盾牌和单手武器。对群怪用 Thunder Clap 和 Demoralizing Shout。",
    ["41fd2f0"] = "Charge，然后留在 Defensive Stance。对近战攻击你的怪物保持 Shield Block，对施法者则跳过 Shield Block。Revenge 每次亮起就用；对活得久的怪物用 Rend 和几个 Sunder Armor；对群怪用 Thunder Clap 和 Demoralizing Shout。",
    ["b604238"] = "有 Vanguard 时，你可以在 Defensive Stance 中使用 Charge：如果你脱离战斗，可以不换姿态就开始一次拉怪。",
    ["c9e7c22"] = "Shield Wall：12秒内伤害减少60%，用于不顺利的拉怪。",
    ["3f0c2f4"] = "Shield Slam 是最强的一击（伤害随你的格挡值增长）：先用它，之后立刻 Revenge。如果怒气少，先 Revenge，它消耗更少。",
    ["846367b"] = "Protection 主要想要力量（每点给2点攻击强度和格挡值）。武器选DPS最高的：Revenge 和 Shield Slam 不依赖武器。敏捷不那么重要：它给暴击、闪避和护甲，但不给攻击强度。",
    ["fabdcb6"] = "先 Rend，然后每次亮起就 Overpower（在目标闪避之后）。",
    ["f29cf52"] = "Rend，然后亮起时 Overpower。从20级起，一次攻击之后立刻 Slam。",
    ["60998aa"] = "Sweeping Strikes：你接下来的五次攻击也会打到附近的第二个敌人，这是一次大飞跃。在有多余怒气时先对一个怪物开打，然后拉来第二个怪物，对两个都用 Sweeping Strikes 和 Cleave。",
    ["efc030d"] = "有 Bloodthrill 时，如果目标身上有 Rend，你的主手攻击有20%的几率触发 Overpower：Rend 会一直留在输出循环中到60级。",
    ["98a8fec"] = "Mortal Strike 是你新的主要攻击。",
    ["7caf705"] = "武器比一切都重要：寻找最高的DPS，Arms 要慢速双手武器（每次攻击以及 Mortal Strike 和 Slam 造成更多伤害）。其余属性先看命中（Hit，因为未命中既没有伤害也没有怒气），然后是力量和暴击。敏捷给暴击和闪避，但不给攻击强度。",
    ["ce62f29"] = "对活得久的怪物用 Rend，目标闪避时用 Overpower。如果第二个怪物在目标旁边，把多余的怒气花在 Cleave 上。选一把快速的副手武器：攻击更多，怒气更多。",
    ["1879df1"] = "Death Wish：30秒内你造成的物理伤害多20%且不会被恐惧，但承受的伤害多5%。Reckless Swings（31）：消耗一点生命，你接下来的四次攻击每次多给5点怒气。",
